    if(controller_.running())return false;const auto suggestions=suggestSourceMetadata(path);ImportRow row;row.metadata.path=suggestions.dataPath.toUtf8().toStdString();row.metadata.name=QFileInfo(suggestions.dataPath).fileName().toUtf8().toStdString();row.metadata.demo=false;row.metadata.sampleFormat=suggestions.format.value_or(SampleFormat{});row.metadata.sampleRateHz=suggestions.sampleRateHz.value_or(102.4e6);row.metadata.centerFrequencyHz=suggestions.centerFrequencyHz.value_or(0);row.metadata.declaredBandwidthHz=suggestions.bandwidthHz.value_or(0);row.acquisitionKnown=suggestions.sampleRateHz.has_value()&&suggestions.centerFrequencyHz.has_value();row.confirmed=suggestions.format.has_value()&&suggestions.sampleRateHz.has_value()&&suggestions.centerFrequencyHz.has_value();row.provenance=suggestions.provenance+" "+suggestions.conflicts+" "+suggestions.warnings.left(600);row.error=suggestions.error;row.metadataError=suggestions.error;
