void SignalImportDialog::commitConfiguration(){if(updating_||controller_.running())return;
    constexpr ComponentEncoding encodings[]{ComponentEncoding::Int16,ComponentEncoding::Float32,ComponentEncoding::Int8,ComponentEncoding::UInt8,ComponentEncoding::Int32,ComponentEncoding::Float64};SampleFormat f;f.structure=structure_->currentIndex()?SampleStructure::Real:SampleStructure::ComplexIQ;f.componentEncoding=encodings[encoding_->currentIndex()];
    if(sender()==order_)previousOrder_=order_->currentIndex()?ByteOrder::Big:ByteOrder::Little;if(sender()==layout_)previousLayout_=static_cast<IQLayout>(layout_->currentIndex()+1);
    f.byteOrder=bytesPerComponent(f)==1?ByteOrder::NotApplicable:previousOrder_;f.iqLayout=f.structure==SampleStructure::Real?IQLayout::NotApplicable:previousLayout_;f.normalizeIntegerAdc=f.componentEncoding<ComponentEncoding::Float32&&normalize_->isChecked();
    bool okH=false,okT=false,okC=false;f.headerBytes=header_->text().toULongLong(&okH);f.trailerBytes=trailer_->text().toULongLong(&okT);const auto ch=channels_->text().toUInt(&okC);f.channels=ch;f.channelLayout=channelLayout_->currentIndex()?ChannelLayout::ChannelPlanar:ChannelLayout::TimeInterleaved;
    if(okC&&ch>=1&&ch<=128&&channel_->count()!=static_cast<int>(ch)){const QSignalBlocker block(channel_);const int selected=channel_->currentIndex();channel_->clear();for(std::uint32_t c=0;c<ch;++c)channel_->addItem(QString("CH %1").arg(c));channel_->setCurrentIndex(std::clamp(selected,0,static_cast<int>(ch)-1));}
    f.selectedChannel=static_cast<std::uint32_t>(std::max(0,channel_->currentIndex()));
    if(!okH||!okT||!okC){validation_->setText("偏移与通道必须为有效整数");import_->setEnabled(false);return;}
    if(current_<controller_.rows().size()){
        auto& row=controller_.rows()[current_];const bool changed=row.metadata.sampleFormat!=f||row.metadata.sampleRateHz!=fs_->value()||row.metadata.centerFrequencyHz!=fc_->value()||row.metadata.declaredBandwidthHz!=bw_->value()||row.confirmed!=confirmed_->isChecked();
        row.metadata.sampleFormat=f;row.metadata.sampleRateHz=fs_->value();row.metadata.centerFrequencyHz=fc_->value();row.metadata.declaredBandwidthHz=bw_->value();row.confirmed=confirmed_->isChecked();
        if(changed){row.status=ImportStatus::Pending;row.load={};row.committed=false;if(!row.provenance.contains("已手动覆盖"))row.provenance+=" · 已手动覆盖";}
    }
    refreshSummary();refreshBatch();
}
void SignalImportDialog::refreshSummary(bool doPreview){
    SampleFormat f;if(current_<controller_.rows().size())f=controller_.rows()[current_].metadata.sampleFormat;
    const bool real=f.structure==SampleStructure::Real;orderField_->setVisible(bytesPerComponent(f)>1);layoutField_->setVisible(!real);normalize_->setEnabled(f.componentEncoding<ComponentEncoding::Float32);normalize_->setToolTip(normalize_->isEnabled()?"整数幅度按 ADC 满刻度缩放；磁盘不修改":"浮点保留原值，不采用整数归一化");fsLabel_->setText(real?"实采样率":"复采样率");fcLabel_->setText(real?"频率参考元数据":"RF 中心频率");
    formatCode_->setText(QString::fromStdString(formatId(f)));summary_->setText(QString("%1 · %2 · %3").arg(real?"实数 ADC":"复数 IQ",f.byteOrder==ByteOrder::NotApplicable?"字节序无关":f.byteOrder==ByteOrder::Big?"Big Endian":"Little Endian",real?"单分量实数":f.iqLayout==IQLayout::IQInterleaved?"IQ 交替":f.iqLayout==IQLayout::QIInterleaved?"QI 交替":"I/Q 分量分块"));formatSize_->setText(QString("每通道每时刻 %1 字节 · %2 个分量     磁盘每帧 %3 字节（%4 通道）").arg(bytesPerChannelSample(f)).arg(real?1:2).arg(bytesPerFrame(f)).arg(f.channels));
    if(!import_)return;if(current_>=controller_.rows().size()){import_->setEnabled(false);return;}
    auto& row=controller_.rows()[current_];QString error;FileMetadata m;
    const bool valid=row.metadataError.isEmpty()&&describeRawFile(QString::fromStdString(row.metadata.path),f,fs_->value(),fc_->value(),bw_->value(),m,error);if(!row.metadataError.isEmpty())error=row.metadataError;
    row.error=error;import_->setEnabled(valid&&row.confirmed);validation_->setText(!error.isEmpty()?error:row.confirmed?"格式参数通过基础校验 · "+row.provenance:"请确认采样结构与编码；未识别的参数不会自动按 CI16 导入");
    if(valid){countStat_->setText(QString::number(m.sampleCount));durationStat_->setText(formatAdaptiveValue(static_cast<double>(m.sampleCount)/m.sampleRateHz,UnitKind::Time));frequencyStat_->setText(formatAdaptiveValue(fullRange(m).frequency.lowerHz,UnitKind::Frequency)+" ～ "+formatAdaptiveValue(fullRange(m).frequency.upperHz,UnitKind::Frequency));row.metadata.sampleCount=m.sampleCount;row.metadata.effectiveBandwidthHz=m.effectiveBandwidthHz;stats_->setText(QString("%1 样本/通道　 ·　 %2 s<br>%3 ～ %4%5").arg(m.sampleCount).arg(static_cast<double>(m.sampleCount)/m.sampleRateHz,0,'g',7).arg(formatAdaptiveValue(fullRange(m).frequency.lowerHz,UnitKind::Frequency),formatAdaptiveValue(fullRange(m).frequency.upperHz,UnitKind::Frequency),real?"（实数）":""));footer_->setText(QString("%1 · %2 样本/通道 · %3").arg(QString::fromStdString(formatId(f))).arg(m.sampleCount).arg(row.confirmed?"参数已确认":"需确认"));
        if(doPreview){const long double begin=static_cast<long double>(start_->value())*m.sampleRateHz;const auto start=static_cast<SampleIndex>(std::min<long double>(m.sampleCount-1,begin));preview_->preview(std::move(m),std::min(m.sampleCount-1,previewSample_.value_or(start)));}}
    else {stats_->setText("— 样本　　— 时长　　— 频段");footer_->setText(error);if(doPreview)preview_->clear();}
}
