    if(key==batchKey_)return;batchKey_=key;
    QList<int> selection;for(const auto* item:table_->selectedItems())if(!selection.contains(item->row()))selection.append(item->row());const QSignalBlocker blocker(table_);table_->setRowCount(static_cast<int>(controller_.rows().size()));for(int i=0;i<table_->rowCount();++i){const auto& row=controller_.rows()[i];const auto& m=row.metadata;const auto& f=m.sampleFormat;const QStringList values{QString::fromStdString(m.name),bytesText(static_cast<std::uint64_t>(std::max<qint64>(0,QFileInfo(QString::fromStdString(m.path)).size()))),QString::fromStdString(formatId(f))+QString(" · %1 · %2").arg(f.structure==SampleStructure::Real?"REAL":f.iqLayout==IQLayout::QIInterleaved?"QI":f.iqLayout==IQLayout::PlanarIQ?"I/Q 分块":"IQ",f.byteOrder==ByteOrder::Big?"BE":f.byteOrder==ByteOrder::Little?"LE":"NA"),formatAdaptiveValue(m.sampleRateHz,UnitKind::SampleRate),statusText(row)};for(int c=0;c<5;++c){auto* item=new QTableWidgetItem(values[c]);item->setToolTip(c==4?row.error+"\n"+row.provenance:values[c]);table_->setItem(i,c,item);if(selection.contains(i))item->setSelected(true);}auto* remove=button("×","batchRemove");remove->setToolTip("移除该文件");remove->setEnabled(!controller_.running());table_->setCellWidget(i,5,remove);connect(remove,&QPushButton::clicked,this,[this,i]{if(controller_.running())return;controller_.rows().erase(controller_.rows().begin()+i);current_=controller_.rows().empty()?0:std::min(current_,controller_.rows().size()-1);loadCurrent();refreshBatch();});}
    tabs_[1]->setText(QString("批量导入 (%1)").arg(table_->rowCount()));if(current_<controller_.rows().size()){const auto& row=controller_.rows()[current_];batchSelected_->setText(QString::fromStdString(row.metadata.name)+"\n"+row.provenance+"\n"+statusText(row));}
