void SignalImportDialog::applyTemplate(int index,bool batch){
    if(index<0||static_cast<std::size_t>(index)>=templates_.templates().size())return;
    const auto selected=templates_.templates()[index];const auto f=selected.format;
    if(controller_.running())return;std::vector<std::size_t> rows;if(batch){for(auto* item:table_->selectedItems())if(std::find(rows.begin(),rows.end(),static_cast<std::size_t>(item->row()))==rows.end())rows.push_back(item->row());if(rows.empty())for(std::size_t i=0;i<controller_.rows().size();++i)rows.push_back(i);}else rows.push_back(current_);
    for(auto i:rows)if(i<controller_.rows().size()){
        auto& row=controller_.rows()[i];
        if((row.provenance.contains("SigMF")||row.provenance.contains("已手动覆盖"))&&row.metadata.sampleFormat!=f){
            if(QMessageBox::question(this,"确认格式覆盖",QString::fromStdString(row.metadata.name)+"：模板与现有明确格式不同，覆盖结构与编码？")!=QMessageBox::Yes)continue;
        }
        row.metadata.sampleFormat=f;row.confirmed=row.acquisitionKnown||row.confirmed;row.status=ImportStatus::Pending;
        row.provenance+=" · 用户选定模板："+selected.name+"（Fs/Fc保留）";
    }
    templates_.used(selected.id);loadCurrent();refreshBatch();refreshTemplates();
}
