bjectName("importProgressMetrics");v->addWidget(progressMetrics_);auto* buttons=new QHBoxLayout;buttons->addStretch();stop_=button("停止，保留已读前缀","importProgressStop");finish_=button("完成并进入工程","importProgressFinish");finish_->setProperty("primary",true);restart_=button("重新完整读入","importProgressRestart");buttons->addWidget(stop_);buttons->addWidget(finish_);buttons->addWidget(restart_);v->addLayout(buttons);center->addWidget(card);center->addStretch();outside->addLayout(center);outside->addStretch();overlay_->hide();
    connect(stop_,&QPushButton::clicked,this,[this]{controller_.stopAll();});connect(restart_,&QPushButton::clicked,this,[this]{controller_.restart();previewAfterLoad_=false;updateProgress();});connect(finish_,&QPushButton::clicked,this,[this]{if(!controller_.canCommit())return;for(auto file:controller_.sources()){QString error;const auto metadata=file.metadata;if(commitSource&&!commitSource(std::move(file),error)){progressDescription_->setText(error);return;}controller_.markCommitted(metadata);}accept();});
