void SignalImportDialog::startImport(){commitConfiguration();std::vector<std::size_t> indices;if(pages_->currentIndex()==1){for(const auto* item:table_->selectedItems())if(std::find(indices.begin(),indices.end(),static_cast<std::size_t>(item->row()))==indices.end())indices.push_back(item->row());if(indices.empty())for(std::size_t i=0;i<controller_.rows().size();++i)indices.push_back(i);}else indices.push_back(current_);controller_.start(indices);previewAfterLoad_=false;overlay_->setGeometry(rect());overlay_->show();overlay_->raise();updateProgress();}
void SignalImportDialog::pollImport(){if(!overlay_->isVisible())return;controller_.poll();updateProgress();}
void SignalImportDialog::updateProgress(){if(!overlay_||!overlay_->isVisible())return;
    std::uint64_t total=0,loaded=0,bytes=0,targetBytes=0;bool partial=false;QString errors;
    for(const auto& row:controller_.rows()){if(row.load.target){total+=row.load.target;loaded+=row.load.loaded;const auto unit=row.metadata.sampleFormat.channelLayout==ChannelLayout::ChannelPlanar?bytesPerChannelSample(row.metadata.sampleFormat):bytesPerFrame(row.metadata.sampleFormat);bytes+=row.load.loaded*unit;targetBytes+=row.load.target*unit;}partial|=row.status==ImportStatus::Partial;if(!row.error.isEmpty())errors+=QString::fromStdString(row.metadata.name)+"："+row.error+"\n";}
    progress_->setValue(total?static_cast<int>(1000.L*loaded/total):0);progressMetrics_->setText(QString("%1 / %2 · %3% · %4 / %5 样本帧").arg(bytesText(bytes),bytesText(targetBytes)).arg(total?static_cast<int>(100.L*loaded/total):0).arg(loaded).arg(total));
    const bool running=controller_.running();stop_->setVisible(running);restart_->setVisible(!running&&(partial||!controller_.canCommit()));finish_->setVisible(!running);finish_->setEnabled(controller_.canCommit()&&previewAfterLoad_&&preview_->ready());
    const bool complete[]{total>0,!running&&loaded>0,!running&&preview_->ready()};for(int i=0;i<3;++i){stageIndicators_[i]->setText(complete[i]?"✓":QString::number(i+1));stageIndicators_[i]->setStyleSheet(complete[i]?"background:#1b655c;color:#85f0d0;border-radius:11px;":"background:#2d516a;color:#a9c9da;border-radius:11px;");}
    if(running){progressTitle_->setText(controller_.rows().size()>1?QString("正在导入 %1 个数据文件").arg(controller_.rows().size()):"正在建立信号数据源");return;}
    if(!previewAfterLoad_&&controller_.canCommit()){previewAfterLoad_=true;const auto sources=controller_.sources();preview_->preview(sources.front().metadata);}
    progressTitle_->setText(partial?"读入已停止 · 已保留样本前缀":controller_.canCommit()?"数据源已就绪":"没有可用数据源");progressDescription_->setText(!errors.isEmpty()?errors:partial?"完成的读取块已保留，超出可用前缀的数据不参与后续分析。":"顺序读入状态完成，已准备首屏预览及工程元数据。");finish_->setText(partial?"保留前缀并进入工程":"完成并进入工程");refreshBatch();
}
void SignalImportDialog::resizeEvent(QResizeEvent* event){QDialog::resizeEvent(event);if(overlay_)overlay_->setGeometry(rect());}
void SignalImportDialog::mousePressEvent(QMouseEvent* event){if(event->button()==Qt::LeftButton&&event->position().y()<73&&windowHandle()){windowHandle()->startSystemMove();event->accept();return;}QDialog::mousePressEvent(event);}
void SignalImportDialog::reject(){controller_.stopAll();QDialog::reject();}
void SignalImportDialog::dragEnterEvent(QDragEnterEvent* event){if(event->mimeData()->hasUrls()&&!controller_.running())event->acceptProposedAction();}
void SignalImportDialog::dropEvent(QDropEvent* event){for(const auto& url:event->mimeData()->urls())if(url.isLocalFile())addPath(url.toLocalFile());event->acceptProposedAction();}
